  1→//! Sensitive step handling.
  2→//!
  3→//! This module provides special handling for steps that process sensitive data.
  4→
  5→/// Manages sensitive step execution.
  6→///
  7→/// # Example
  8→///
  9→/// ```
 10→/// use bivvy::steps::SensitiveStepHandler;
 11→///
 12→/// // Configure handler based on execution mode
 13→/// let handler = SensitiveStepHandler::new(false, false);
 14→///
 15→/// // Dry-run hides the actual command
 16→/// let handler_dry = SensitiveStepHandler::new(true, false);
 17→/// let display = handler_dry.dry_run_display("vault read secret/key");
 18→/// assert!(display.contains("SENSITIVE"));
 19→///
 20→/// // Sensitive output is not logged
 21→/// assert!(!handler.should_log_output());
 22→///
 23→/// // In non-interactive mode, no confirmation needed
 24→/// let handler_non_interactive = SensitiveStepHandler::new(false, true);
 25→/// assert!(!handler_non_interactive.should_confirm("fetch-secrets"));
 26→/// ```
 27→pub struct SensitiveStepHandler {
 28→    /// Whether running in dry-run mode.
 29→    is_dry_run: bool,
 30→    /// Whether running in non-interactive mode.
 31→    is_non_interactive: bool,
 32→}
 33→
 34→impl SensitiveStepHandler {
 35→    /// Create a new handler with the given settings.
 36→    pub fn new(is_dry_run: bool, is_non_interactive: bool) -> Self {
 37→        Self {
 38→            is_dry_run,
 39→            is_non_interactive,
 40→        }
 41→    }
 42→
 43→    /// Check if user should confirm before running sensitive step.
 44→    ///
 45→    /// Confirmation is skipped in non-interactive mode or CI.
 46→    pub fn should_confirm(&self, _step_name: &str) -> bool {
 47→        // Don't confirm in non-interactive mode or CI
 48→        if self.is_non_interactive {
 49→            return false;
 50→        }
 51→        if std::env::var("CI").is_ok() {
 52→            return false;
 53→        }
 54→        // Always confirm sensitive steps otherwise
 55→        true
 56→    }
 57→
 58→    /// Get display text for dry-run output.
 59→    ///
 60→    /// The actual command is hidden to prevent exposure in logs.
 61→    pub fn dry_run_display(&self, _command: &str) -> String {
 62→        "[SENSITIVE - command hidden in dry-run]".to_string()
 63→    }
 64→
 65→    /// Check if command output should be logged.
 66→    ///
 67→    /// Sensitive steps suppress output logging to prevent data exposure.
 68→    pub fn should_log_output(&self) -> bool {
 69→        false
 70→    }
 71→
 72→    /// Check if running in dry-run mode.
 73→    pub fn is_dry_run(&self) -> bool {
 74→        self.is_dry_run
 75→    }
 76→
 77→    /// Check if running in non-interactive mode.
 78→    pub fn is_non_interactive(&self) -> bool {
 79→        self.is_non_interactive
 80→    }
 81→}
 82→
 83→impl Default for SensitiveStepHandler {
 84→    fn default() -> Self {
 85→        Self::new(false, false)
 86→    }
 87→}
 88→
 89→#[cfg(test)]
 90→mod tests {
 91→    use super::*;
 92→    use std::sync::Mutex;
 93→
 94→    // Mutex to serialize tests that modify CI env var
 95→    static CI_MUTEX: Mutex<()> = Mutex::new(());
 96→
 97→    fn with_ci_env<F, R>(ci_value: Option<&str>, f: F) -> R
 98→    where
 99→        F: FnOnce() -> R,
100→    {
101→        let _guard = CI_MUTEX.lock().unwrap();
102→        let old_ci = std::env::var("CI").ok();
103→        match ci_value {
104→            Some(v) => std::env::set_var("CI", v),
105→            None => std::env::remove_var("CI"),
106→        }
107→        let result = f();
108→        match old_ci {
109→            Some(v) => std::env::set_var("CI", v),
110→            None => std::env::remove_var("CI"),
111→        }
112→        result
113→    }
114→
115→    #[test]
116→    fn dry_run_hides_sensitive_command() {
117→        let handler = SensitiveStepHandler::new(true, false);
118→
119→        let display = handler.dry_run_display("vault read secret/key");
120→
121→        assert!(!display.contains("vault"));
122→        assert!(display.contains("SENSITIVE"));
123→    }
124→
125→    #[test]
126→    fn sensitive_output_not_logged() {
127→        let handler = SensitiveStepHandler::new(false, false);
128→
129→        assert!(!handler.should_log_output());
130→    }
131→
132→    #[test]
133→    fn no_confirm_in_non_interactive() {
134→        let handler = SensitiveStepHandler::new(false, true);
135→
136→        assert!(!handler.should_confirm("any-step"));
137→    }
138→
139→    #[test]
140→    fn confirm_in_interactive_mode() {
141→        with_ci_env(None, || {
142→            let handler = SensitiveStepHandler::new(false, false);
143→            assert!(handler.should_confirm("sensitive-step"));
144→        });
145→    }
146→
147→    #[test]
148→    fn no_confirm_in_ci() {
149→        with_ci_env(Some("true"), || {
150→            let handler = SensitiveStepHandler::new(false, false);
151→            assert!(!handler.should_confirm("sensitive-step"));
152→        });
153→    }
154→
155→    #[test]
156→    fn is_dry_run_accessor() {
157→        let handler = SensitiveStepHandler::new(true, false);
158→        assert!(handler.is_dry_run());
159→
160→        let handler = SensitiveStepHandler::new(false, false);
161→        assert!(!handler.is_dry_run());
162→    }
163→
164→    #[test]
165→    fn is_non_interactive_accessor() {
166→        let handler = SensitiveStepHandler::new(false, true);
167→        assert!(handler.is_non_interactive());
168→
169→        let handler = SensitiveStepHandler::new(false, false);
170→        assert!(!handler.is_non_interactive());
171→    }
172→
173→    #[test]
174→    fn default_handler() {
175→        let handler = SensitiveStepHandler::default();
176→        assert!(!handler.is_dry_run());
177→        assert!(!handler.is_non_interactive());
178→    }
179→}
