    #[test]
    fn is_yes_no_returns_true_for_yes_no_options() {
        let options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_true_regardless_of_order() {
        let options = vec![
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_other_options() {
        let options = vec![
            PromptOption {
                label: "Option A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "Option B".to_string(),
                value: "b".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_more_than_two() {
        let options = vec![
            PromptOption {
                label: "Yes".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Maybe".to_string(),
                value: "maybe".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

