    #[test]
    fn map_dialoguer_err_converts_eof_to_interrupted() {
        let eof_err = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        let dialoguer_err: dialoguer::Error = eof_err.into();
        let bivvy_err = map_dialoguer_err(dialoguer_err);
        match bivvy_err {
            BivvyError::Io(ref e) => {
                assert_eq!(e.kind(), std::io::ErrorKind::Interrupted);
                assert!(e.to_string().contains("cancelled"));
            }
            _ => panic!("Expected BivvyError::Io"),
        }
    }

    #[test]
    fn map_dialoguer_err_preserves_other_errors() {
        let other_err = std::io::Error::new(std::io::ErrorKind::NotConnected, "not a terminal");
        let dialoguer_err: dialoguer::Error = other_err.into();
        let bivvy_err = map_dialoguer_err(dialoguer_err);
        match bivvy_err {
            BivvyError::Io(ref e) => {
                assert_eq!(e.kind(), std::io::ErrorKind::NotConnected);
            }
            _ => panic!("Expected BivvyError::Io"),
        }
    }
